"""Checks that source archives track every manifest project, including toolchains."""import sysimport unittestfrom pathlib import Pathsys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'scripts'))import source_snapshotMANIFEST = '''<manifest><remote name="aosp" fetch="https://android.googlesource.com/"/><default remote="aosp" revision="main"/><project name="kernel/common" path="common" revision="lts"/><project name="kernel/build" path="build"/></manifest>'''class SnapshotTests(unittest.TestCase):    def test_all_projects_are_pinned_and_identity_is_stable(self):        calls = []        def resolve(url, ref):            calls.append((url, ref))            return ('a' if ref == 'lts' else 'b') * 40        locked, digest = source_snapshot.lock_manifest(MANIFEST, resolve)        self.assertIn('revision="' + 'a'*40 + '"', locked)        self.assertIn('revision="' + 'b'*40 + '"', locked)        self.assertEqual(digest, source_snapshot.lock_manifest(MANIFEST, resolve)[1])        self.assertIn(('https://android.googlesource.com/kernel/build', 'main'), calls)    def test_toolchain_change_invalidates_snapshot(self):        first = source_snapshot.lock_manifest(MANIFEST, lambda u,r: 'a'*40)[1]        second = source_snapshot.lock_manifest(MANIFEST, lambda u,r: ('b' if u.endswith('build') else 'a')*40)[1]        self.assertNotEqual(first, second)    def test_pinned_revision_does_not_need_network(self):        text = MANIFEST.replace('revision="lts"', 'revision="'+'c'*40+'"')        calls=[]        source_snapshot.lock_manifest(text, lambda u,r: calls.append(r) or 'a'*40)        self.assertEqual(calls, ['main'])    def test_missing_remote_is_rejected(self):        with self.assertRaises(ValueError):            source_snapshot.lock_manifest('<manifest><project name="common"/></manifest>',lambda u,r:'a'*40)    def test_relative_remote_matches_repo_url(self):        text=MANIFEST.replace('https://android.googlesource.com/','..')        calls=[]        source_snapshot.lock_manifest(text,lambda u,r:calls.append(u) or 'a'*40)        self.assertIn('https://android.googlesource.com/kernel/common', calls)    def test_extra_gcc_revision_invalidates_snapshot(self):        first = source_snapshot.lock_manifest(MANIFEST, lambda u,r: 'a'*40, extra_revision='b'*40)[1]        second = source_snapshot.lock_manifest(MANIFEST, lambda u,r: 'a'*40, extra_revision='c'*40)[1]        self.assertNotEqual(first, second)